#!/usr/bin/env python3

with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

# Count different banana patterns
patterns = {}
for line in content.split('\n'):
    for word in line.split():
        if word.lower() == 'banana':
            if word in patterns:
                patterns[word] += 1
            else:
                patterns[word] = 1

# Print patterns and their counts
