#!/usr/bin/env python3

with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

# Identify all possible "banana" patterns (case-sensitive)
banana_variants = []
for i in range(2**6):  # 6 is the length of "banana"
    pattern = ""
    for j in range(6):
        if (i >> j) & 1:
            pattern += "banana"[j].upper()
        else:
            pattern += "banana"[j].lower()
    banana_variants.append(pattern)

# Count occurrences of each pattern
pattern_counts = {variant: 0 for variant in banana_variants}
for i in range(len(content) - 5):
    window = content[i:i+6]
    if window.lower() == "banana":
        if window in pattern_counts:
            pattern_counts[window] += 1

# Print results
print("Banana pattern occurrences:")
for pattern, count in sorted(pattern_counts.items(), key=lambda x: x[1], reverse=True):
    if count > 0:
        print(f"{pattern}: {count}")

# Also print sequences of consecutive patterns to see if there are meaningful instructions
print("\nSample of banana sequences from the file:")
found_patterns = []
for i in range(0, len(content) - 5, 6):
    window = content[i:i+6]
    if window.lower() == "banana":
        found_patterns.append(window)

# Print first 20 patterns if found
if found_patterns:
    print(" ".join(found_patterns[:20]))

#!/usr/bin/env python3

def count_patterns(file_path):
    with open(file_path, 'r') as f:
        content = f.read()

    patterns = {}
    current_pattern = ""

    for char in content:
        if char.lower() in 'bans':
            current_pattern += char
            if current_pattern.lower() == 'banana':
                if current_pattern in patterns:
                    patterns[current_pattern] += 1
                else:
                    patterns[current_pattern] = 1
                current_pattern = ""
        else:
            if current_pattern:
                current_pattern = ""

    return patterns

patterns = count_patterns('/home/ctfplayer/ctf_files/banana.script')
print(f"Total unique patterns: {len(patterns)}")
for pattern, count in sorted(patterns.items(), key=lambda x: x[1], reverse=True):
    print(f"{pattern}: {count}")

#!/usr/bin/env python3

def get_banana_patterns():
    patterns = []
    # Generate all 64 possible capitalization patterns of "banana"
    for i in range(64):
        pattern = ""
        for j in range(6):
            if (i >> j) & 1:
                pattern += "BANANA"[j]
            else:
                pattern += "banana"[j]
        patterns.append(pattern)
    return patterns

# Read the banana.script file
with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

# Count each pattern
counts = {}
patterns = get_banana_patterns()

for pattern in patterns:
    count = content.count(pattern)
    if count > 0:
        counts[pattern] = count

# Print patterns sorted by frequency
for pattern, count in sorted(counts.items(), key=lambda x: x[1], reverse=True):
    print(f"{pattern}: {count}")

print(f"\nTotal unique patterns found: {len(counts)}")

