#!/usr/bin/env python3

def analyze_banana_script():
    with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
        content = f.read()

    # Split by whitespace to get each banana pattern
    patterns = content.split()

    # Analyze the first 20 patterns in detail
    print("First 20 patterns and their characteristics:")
    for i, pattern in enumerate(patterns[:20]):
        # Ignore non-banana patterns
        if not pattern.lower().startswith('banana'):
            continue

        # Convert to binary representation (1 for uppercase, 0 for lowercase)
        binary = ''
        for c in pattern:
            binary += '1' if c.isupper() else '0'

        print(f"{i}: {pattern} -> {binary}")

    # Count occurrences of each pattern
    pattern_count = {}
    for p in patterns:
        if p in pattern_count:
            pattern_count[p] += 1
        else:
            pattern_count[p] = 1

    # Print the most common patterns
    print("\nMost common patterns:")
    for pattern, count in sorted(pattern_count.items(), key=lambda x: x[1], reverse=True)[:10]:
        binary = ''.join('1' if c.isupper() else '0' for c in pattern)
        print(f"{pattern} ({binary}): {count} occurrences")

if __name__ == "__main__":
    analyze_banana_script()

#!/usr/bin/env python3

def analyze_banana_script():
    with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
        content = f.read()

    # Find all banana patterns (case-sensitive)
    tokens = content.split()
    banana_patterns = [token for token in tokens if token.lower() == 'bananas']

    # Count unique patterns
    unique_patterns = set(banana_patterns)
    print(f"Found {len(banana_patterns)} total banana patterns")
    print(f"Found {len(unique_patterns)} unique banana patterns")

    # Create dictionary of case patterns (ignoring the 's' at the end)
    case_patterns = {}
    for pattern in unique_patterns:
        pattern_core = pattern[:-1]  # Remove the 's'
        case_pattern = ''.join('1' if c.isupper() else '0' for c in pattern_core)
        if case_pattern in case_patterns:
            case_patterns[case_pattern].append(pattern)
        else:
            case_patterns[case_pattern] = [pattern]

    # Display stats
    print(f"Found {len(case_patterns)} unique case patterns")

    # Check if all binary patterns from 0 to 63 are present
    missing_patterns = []
    for i in range(64):
        binary = format(i, '06b')  # Get 6-bit binary representation
        if binary not in case_patterns:
            missing_patterns.append(binary)

    if missing_patterns:
        print(f"Missing binary patterns: {missing_patterns}")
    else:
        print("All possible 64 binary patterns are present!")

    # Print all binary patterns and their corresponding banana pattern
    print("\nAll binary patterns and their banana representation:")
    for i in range(64):
        binary = format(i, '06b')  # Get 6-bit binary representation
        if binary in case_patterns:
            print(f"{binary} -> {case_patterns[binary][0]}")
        else:
            print(f"{binary} -> [Missing]")

    # Get the sequence of instructions (first 20)
    print("\nFirst 20 instructions in the script:")
    for i, pattern in enumerate(banana_patterns[:20]):
        pattern_core = pattern[:-1]  # Remove the 's'
        binary = ''.join('1' if c.isupper() else '0' for c in pattern_core)
        decimal = int(binary, 2)
        print(f"{i+1}: {pattern} -> {binary} (decimal: {decimal})")

if __name__ == "__main__":
    analyze_banana_script()

