#!/usr/bin/env python3

def pattern_to_binary(pattern):
    """Convert a 'banana' pattern to its binary representation"""
    binary = ""
    for i, char in enumerate("banana"):
        if pattern[i].isupper():
            binary += "1"
        else:
            binary += "0"
    return binary

# Read the banana.script file
with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    script = f.read()

# Find all unique banana patterns and convert to binary
pattern_to_bin = {}
bin_to_pattern = {}
instruction_sequence = []

for i in range(0, len(script) - 6):
    if script[i:i+6].lower() == "banana":
        pattern = script[i:i+7]  # Include the 's' at the end
        if len(pattern) == 7 and pattern[6].lower() == 's':
            binary = pattern_to_binary(pattern[:6])
            pattern_to_bin[pattern] = binary
            bin_to_pattern[binary] = pattern
            instruction_sequence.append((i, pattern, binary))

# Print the mapping
print("Pattern to Binary Mapping:")
for pattern, binary in sorted(pattern_to_bin.items(), key=lambda x: x[1]):
    print(f"{pattern}: {binary} (Decimal: {int(binary, 2)})")

# Print the first 20 instructions in the sequence
print("\nFirst 20 instructions:")
for i, (pos, pattern, binary) in enumerate(instruction_sequence[:20]):
    print(f"{i+1}. Position {pos}: {pattern} -> {binary} (Decimal: {int(binary, 2)})")

# Print total instruction count
print(f"\nTotal instructions in sequence: {len(instruction_sequence)}")

# Check for patterns
print("\nAnalyzing instruction sequence for patterns...")
decimal_sequence = [int(binary, 2) for _, _, binary in instruction_sequence[:100]]
print(f"First 100 decimal values: {decimal_sequence}")

# Binary ASCII analysis
print("\nTrying to interpret as binary ASCII:")
binary_chunks = []
current_chunk = ""
for _, _, binary in instruction_sequence[:50]:
    current_chunk += binary
    if len(current_chunk) >= 8:
        binary_chunks.append(current_chunk[:8])
        current_chunk = current_chunk[8:]

print("ASCII from 8-bit chunks:")
for chunk in binary_chunks:
    try:
        char = chr(int(chunk, 2))
        print(f"{chunk} -> {int(chunk, 2)} -> {char if char.isprintable() else '.'}")
    except:
        print(f"{chunk} -> conversion error")
